parameters.jsCode:
// 1. Get first item
const firstItem = $input.first();

// Get existing binary (if any)
const binary = firstItem.binary || {};

// 2. Extract jobs
const payload = firstItem.json;
const jobs = payload.jobs || [];

// 3. Return jobs + keep binary
return jobs.map(job => ({
  json: {
    ...job,
    search_metadata: {
      search_term: payload.search_term,
      location: payload.location,
      timestamp: payload.timestamp,
      backup_file: payload.backup_file,
      sites_searched: payload.sites_searched
    }
  },

  // IMPORTANT: forward binary
  binary
}));

const items = $input.all();
if (items.length === 0) return { json: { total_matches: 0 } };

// Define column order to match your required format
const orderedColumns = [
  'id', 'site', 'job_url', 'job_url_direct', 'title', 'company', 'location',
  'date_posted', 'job_type', 'salary_source', 'interval', 'min_amount',
  'max_amount', 'currency', 'is_remote', 'job_level', 'job_function',
  'listing_type', 'emails', 'description', 'company_industry', 'company_url',
  'company_logo', 'company_url_direct', 'company_addresses', 'company_num_employees',
  'company_revenue', 'company_description', 'skills', 'experience_range',
  'company_rating', 'company_reviews_count', 'vacancy_count', 'work_from_home_type'
];

// Collect any extra columns not in the predefined list
const allKeys = new Set(orderedColumns);
items.forEach(item => {
  Object.keys(item.json).forEach(key => allKeys.add(key));
});
const headers = Array.from(allKeys);

// Create CSV String
let csvString = headers.join(",") + "\n";

items.forEach(item => {
  const row = headers.map(header => {
    let value = item.json[header];

    if (Array.isArray(value)) value = value.join("; ");
    else if (value && typeof value === 'object') value = JSON.stringify(value);

    const cleanValue =
      value === null || value === undefined
        ? ""
        : String(value)
            .replace(/"/g, '""')
            .replace(/\n/g, " ")
            .replace(/\r/g, "");

    return `"${cleanValue}"`;
  });

  csvString += row.join(",") + "\n";
});

// Convert to Base64 (no await, no helper)
const base64Data = Buffer.from(csvString).toString('base64');

const fileName = `Job_Matches_${new Date().toISOString().split('T')[0]}.csv`;

return {
  json: {
    csv_base64: base64Data,
    total_matches: items.length,
    fileName,
    chat_id: $('Telegram Trigger').first().json.callback_query.message.chat.id
  },

  binary: {
    data: {
      data: base64Data,
      mimeType: 'text/csv',
      fileName
    }
  }
};

const row = $input.first();

if (!row || !row.json.csv_document) {
  return [];
}

return [{
  json: {
    chat_id: row.json.user_id,
  },

  binary: {
    data: {
      data: row.json.csv_document,
      mimeType: 'text/csv',
      fileName: `Job_Matches_${new Date().toISOString().split('T')[0]}.csv`
    }
  }
}];

