const row = $input.first();

if (!row || !row.json.csv_document) {
  return [];
}

const chatId = $('Telegram Trigger').first().json.message.chat.id;
const table_Name = `session_${chatId}_${Date.now()}`;


return [{
  json: {
    chat_id: row.json.user_id,
    tableName : table_Name
  },
  binary: {
    data: {
      data: row.json.csv_document,
      mimeType: 'text/csv',
      fileName: `Job_Matches_${new Date().toISOString().split('T')[0]}.csv`
    },

  }
}];

// Get all incoming rows
const items = $input.all();

// Helper: Proper CSV Escape
function csvEscape(value) {
  if (value === null || value === undefined) return "";

  let str = String(value);

  // Escape quotes
  str = str.replace(/"/g, '""');

  // Wrap if needed
  if (str.search(/("|,|\n)/g) >= 0) {
    str = `"${str}"`;
  }

  return str;
}

// Headers
const headers = [
  "Score",
  "Company",
  "Location",
  "Job_Url",
  "CV",
  "CreatedAt"
];

// Build rows
const rows = items.map(item => {
  const r = item.json;

  return [
    csvEscape(r.Score),
    csvEscape(r.Company),
    csvEscape(r.Location),
    csvEscape(r.Job_Url),
    csvEscape(r.cv),
    csvEscape(r.createdAt),
  ].join(",");
});

// Build CSV
const csv =
  headers.join(",") + "\n" +
  rows.join("\n");

// Convert to Base64
const base64 = Buffer.from(csv, "utf8").toString("base64");

// File name
const fileName = `job_results_${Date.now()}.csv`;

// Get chat id safely
const chatId =
  $('Telegram Trigger').first().json.message.chat.id;

// Return
return [
  {
    json: {
      fileName,
      total_rows: rows.length,
      chat_id: chatId,
      table_name: $('extracting data in form of file from db').first().json.tableName
    },

    binary: {
      data: {
        data: base64,
        mimeType: "text/csv",
        fileName,
      },
    },
  },
];

const chatId =
  $json.callback_query?.message?.chat?.id ||
  $json.message?.chat?.id ||
  $json.chat?.id;

return {
  json: {
    ...$json,
    chat_id: chatId,
  },
};
